# Dated local subjects, content-bound model registry and deterministic replay.
.cr_rs_types <- c('customer','obligor','facility','issue','transaction','portfolio')
.cr_rs_relations <- c('legal_obligor','joint_liability','economic_dependency','default_correlation','data_identity','contains','pd_reference')
.cr_rs_object <- function(x,name) { if(inherits(x,'CalcResult')) x<-x$value; if(!is.list(x)||is.null(names(x))) .cr_error('RATING_SCHEMA',paste(name,'must be an object')); .cr_hash(x); x }
.cr_rs_string <- function(x,name) { if(!is.character(x)||length(x)!=1L||is.na(x)||!nzchar(trimws(x))) .cr_error('RATING_SCHEMA',paste(name,'must be a nonempty string')); x }
.cr_rs_number <- function(x,name) { if(!is.numeric(x)||length(x)!=1L||!is.finite(x)) .cr_error('RATING_SCHEMA',paste(name,'must be finite numeric')); x }
.cr_rs_dates <- function(as_of,known_at) { a<-.cr_data_date(as_of,'as_of'); k<-.cr_data_date(known_at,'known_at'); if(a>k) .cr_error('RATING_DATE_ORDER','Economic date follows knowledge cutoff'); list(a=a,k=k) }
.cr_rs_interval <- function(row) { .cr_data_required(row,c('effective_from','known_at')); start<-.cr_data_date(row$effective_from,'effective_from'); end<-if(is.null(row$effective_to))NULL else .cr_data_date(row$effective_to,'effective_to'); .cr_data_date(row$known_at,'known_at'); if(!is.null(end)&&end<=start) .cr_error('RATING_DATE_ORDER','Effective interval must be nonempty [from,to)'); list(start=start,end=end) }
.cr_rs_effective <- function(row,a,k) { d<-.cr_rs_interval(row); .cr_data_date(row$known_at,'known_at')<=k&&d$start<=a&&(is.null(d$end)||a<d$end) }
.cr_rs_seal <- function(x,key) { x[[key]]<-NULL; x[[key]]<-.cr_hash(x); x }
.cr_rs_sealed <- function(x,key,name) { x<-.cr_rs_object(x,name); expected<-x[[key]]; x[[key]]<-NULL; if(is.null(expected)||!identical(.cr_hash(x),expected)) .cr_error('RATING_INTEGRITY',paste(name,'hash missing or mismatched')); x[[key]]<-expected; if(!identical(x$schema_version,'1.0')) .cr_error('RATING_SCHEMA',paste('Unsupported',name,'schema')); x }
.cr_rs_sort <- function(rows,fields) { if(!length(rows)) return(rows); args<-lapply(fields,function(f)vapply(rows,function(r)r[[f]],if(is.numeric(rows[[1]][[f]]))numeric(1) else character(1))); rows[do.call(order,c(args,list(method='radix')))] }
.cr_rs_snapshot <- function(snapshot,as_of,known_at) {
  s<-.cr_rs_object(snapshot,'subject snapshot'); .cr_data_required(s,c('subject_id','subject_type','as_of','known_at','attributes')); if(!(s$subject_type %in% .cr_rs_types)) .cr_error('RATING_SCHEMA','Unsupported subject type'); d<-.cr_rs_dates(as_of,known_at)
  if(.cr_data_date(s$as_of,'snapshot.as_of')!=d$a||.cr_data_date(s$known_at,'snapshot.known_at')>d$k) .cr_error('RATING_SNAPSHOT_DATE','Snapshot must match economic date and be known by cutoff')
  attrs<-.cr_rs_object(s$attributes,'attributes'); values<-list(subject_type=s$subject_type,subject_id=s$subject_id); findings<-list()
  for(field in names(attrs)) { if(field %in% names(values)) .cr_error('RATING_SCHEMA','Attribute conflicts with subject identity'); fact<-.cr_rs_object(attrs[[field]],field); .cr_data_required(fact,c('observed_at','known_at')); if(!('value' %in% names(fact))) .cr_error('RATING_SCHEMA','Attribute requires explicit value'); observed<-.cr_data_date(fact$observed_at,'observed_at'); available<-.cr_data_date(fact$known_at,'known_at'); if(available<observed) .cr_error('RATING_DATE_ORDER','Attribute known before observed'); if(observed>d$a||available>.cr_data_date(s$known_at,'snapshot.known_at')) {findings[[length(findings)+1L]]<-list(field=field,code='UNAVAILABLE');values[field]<-list(NULL)} else values[field]<-list(fact$value) }
  list(snapshot=s,values=values,findings=findings)
}

build_rating_subjects <- function(tables,links,as_of,known_at) {
  tables<-.cr_rs_object(tables,'tables'); d<-.cr_rs_dates(as_of,known_at); if(any(!names(tables) %in% .cr_rs_types)) .cr_error('RATING_SCHEMA','Unknown subject table'); nodes<-list(); conflicts<-list()
  for(typ in sort(names(tables),method='radix')) { rows<-.cr_data_rows(tables[[typ]],typ); .cr_data_unique(rows,c('subject_id','version'),typ); for(row in rows) { .cr_data_required(row,c('subject_id','version','attributes')); .cr_rs_string(row$version,'version'); .cr_rs_object(row$attributes,'attributes'); .cr_rs_interval(row); if('subject_type' %in% names(row)) .cr_error('RATING_SCHEMA','Subject type belongs to table name') }
    for(id in sort(unique(vapply(rows,function(r)r$subject_id,character(1))),method='radix')) { active<-Filter(function(r)r$subject_id==id&&.cr_rs_effective(r,d$a,d$k),rows); if(length(active)>1L) conflicts[[length(conflicts)+1L]]<-list(subject_type=typ,subject_id=id,code='OVERLAPPING_VERSIONS',versions=as.list(sort(vapply(active,function(r)r$version,character(1)),method='radix'))) else if(length(active)) nodes[[length(nodes)+1L]]<-c(list(subject_type=typ),active[[1]]) }
  }
  edges<-list(); unresolved<-list(); links<-.cr_data_rows(links,'links'); .cr_data_unique(links,'link_id','links')
  for(edge in .cr_rs_sort(links,'link_id')) { .cr_data_required(edge,c('link_id','relation','from_type','from_id','to_type','to_id')); if(!(edge$relation %in% .cr_rs_relations)||!(edge$from_type %in% .cr_rs_types)||!(edge$to_type %in% .cr_rs_types)) .cr_error('RATING_SCHEMA','Unsupported relationship or subject type'); if(!.cr_rs_effective(edge,d$a,d$k)) next; exists_node<-function(typ,id) any(vapply(nodes,function(n)n$subject_type==typ&&n$subject_id==id,logical(1))); if(!exists_node(edge$from_type,edge$from_id)||!exists_node(edge$to_type,edge$to_id)) unresolved[[length(unresolved)+1L]]<-list(link_id=edge$link_id,code='UNRESOLVED_ENDPOINT') else edges[[length(edges)+1L]]<-edge }
  .cr_result(list(schema_version='1.0',as_of=as_of,known_at=known_at,subjects=nodes,links=edges,conflicts=conflicts,unresolved_links=unresolved),'rating_system.build_rating_subjects',limitations='Relationships never copy PD, grade, LGD or loss between subject levels.')
}
.cr_rs_condition <- function(condition,values) {
  c<-.cr_rs_object(condition,'condition'); .cr_data_required(c,c('field','operator')); .cr_rs_string(c$field,'condition.field'); op<-c$operator; value<-values[[c$field]]
  if(!(op %in% c('eq','ne','lt','le','gt','ge','in','not_in','present','absent'))) .cr_error('RATING_RULE','Unsupported operator')
  if(op=='present') return(!is.null(value)); if(op=='absent') return(is.null(value)); if(!('value' %in% names(c))) .cr_error('RATING_RULE','Comparison requires value'); expected<-c$value
  if(op %in% c('in','not_in')&&(!is.list(expected)||!is.null(names(expected)))) .cr_error('RATING_RULE','Membership requires a list')
  if(op %in% c('lt','le','gt','ge')) {.cr_rs_number(expected,'condition.value');if(!is.null(value)) .cr_rs_number(value,c$field)}
  if(is.null(value)) return(FALSE)
  if(op %in% c('eq','ne')) { same<-identical(.cr_hash(value),.cr_hash(expected)); return(if(op=='eq')same else !same) }
  if(op %in% c('in','not_in')) {member<-any(vapply(expected,function(v)identical(.cr_hash(v),.cr_hash(value)),logical(1)));return(if(op=='in')member else !member)}
  switch(op,lt=value<expected,le=value<=expected,gt=value>expected,ge=value>=expected)
}
route_rating_profile <- function(snapshot,rules,as_of,known_at) {
  s<-.cr_rs_snapshot(snapshot,as_of,known_at); d<-.cr_rs_dates(as_of,known_at); rules<-.cr_data_rows(rules,'rules'); .cr_data_unique(rules,'rule_id','rules'); trace<-list(); matches<-list()
  for(r in rules) { .cr_data_required(r,c('rule_id','profile_id','profile_version','priority','conditions')); .cr_rs_string(r$profile_version,'profile_version'); .cr_rs_number(r$priority,'priority'); conditions<-.cr_data_rows(r$conditions,'conditions'); evaluated<-lapply(conditions,.cr_rs_condition,values=s$values); active<-.cr_rs_effective(r,d$a,d$k); matched<-active&&all(unlist(evaluated)); trace[[length(trace)+1L]]<-list(rule_id=r$rule_id,priority=r$priority,effective=active,condition_matches=evaluated,matched=matched); if(matched) matches[[length(matches)+1L]]<-r }
  best<-if(!length(matches))list() else Filter(function(r)r$priority==min(vapply(matches,function(v)v$priority,numeric(1))),matches); one<-length(best)==1L
  .cr_result(list(status=if(!length(best))'NO_ROUTE' else if(!one)'AMBIGUOUS' else 'ROUTED',profile_id=if(one)best[[1]]$profile_id else NULL,profile_version=if(one)best[[1]]$profile_version else NULL,rule_id=if(one)best[[1]]$rule_id else NULL,candidate_rule_ids=as.list(sort(vapply(best,function(r)r$rule_id,character(1)),method='radix')),trace=.cr_rs_sort(trace,c('priority','rule_id')),unavailable_features=s$findings),'rating_system.route_rating_profile')
}
assess_rating_applicability <- function(snapshot,contract,as_of,known_at) {
  s<-.cr_rs_snapshot(snapshot,as_of,known_at); c<-.cr_rs_object(contract,'applicability contract'); .cr_data_required(c,c('contract_id','version','required_features','allowed_values','support_bounds','maximum_age_days')); required<-c$required_features
  if(!is.list(required)||!is.null(names(required))||any(!vapply(required,function(x)is.character(x)&&length(x)==1L,logical(1)))||anyDuplicated(unlist(required))) .cr_error('RATING_SCHEMA','required_features must be distinct names')
  allowed<-.cr_rs_object(c$allowed_values,'allowed_values'); bounds<-.cr_rs_object(c$support_bounds,'support_bounds'); ages<-.cr_rs_object(c$maximum_age_days,'maximum_age_days'); findings<-s$findings; incompatible<-FALSE
  add<-function(field,code) findings[[length(findings)+1L]]<<-list(field=field,code=code)
  for(name in names(allowed)) { options<-allowed[[name]]; if(!is.list(options)||!length(options)||!is.null(names(options))) .cr_error('RATING_SCHEMA','Allowed values require nonempty lists'); if(is.null(s$values[[name]])) add(name,'MISSING_APPLICABILITY_FIELD') else if(!any(vapply(options,function(v)identical(.cr_hash(s$values[[name]]),.cr_hash(v)),logical(1)))) {incompatible<-TRUE;add(name,'OUTSIDE_APPLICABILITY')} }
  for(name in required) if(is.null(s$values[[name]])) add(name,'MISSING_REQUIRED')
  for(name in names(bounds)) {pair<-bounds[[name]]; if(length(pair)!=2L||.cr_rs_number(pair[[1]],name)>.cr_rs_number(pair[[2]],name)) .cr_error('RATING_SCHEMA','Support requires numeric ordered bounds'); value<-s$values[[name]]; if(!is.null(value)&&(.cr_rs_number(value,name)<pair[[1]]||value>pair[[2]])) add(name,'OUTSIDE_TRAINING_SUPPORT') }
  for(name in names(ages)) {limit<-.cr_data_days(ages[[name]],name); if(name %in% names(s$snapshot$attributes)&&!is.null(s$values[[name]])&&as.numeric(.cr_data_date(as_of,'as_of')-.cr_data_date(s$snapshot$attributes[[name]]$observed_at,'observed_at'))>limit) add(name,'STALE') }
  for(name in names(s$snapshot$attributes)) {conflict<-s$snapshot$attributes[[name]]$conflict;if(!is.null(conflict)&&!identical(conflict,FALSE))add(name,'SOURCE_CONFLICT')}
  .cr_result(list(status=if(incompatible)'NOT_APPLICABLE' else if(length(findings))'REFER' else 'APPLICABLE',findings=.cr_rs_sort(findings,c('field','code')),required_count=length(required),observed_required_count=sum(vapply(required,function(f)!is.null(s$values[[f]]),logical(1))),contract_id=c$contract_id,contract_version=c$version),'rating_system.assess_rating_applicability',limitations='Applicability and marginal support checks are not credit approval or empirical model validation.')
}
.cr_rs_registry <- function(registry) {
  if(is.null(registry)) return(.cr_rs_seal(list(schema_version='1.0',entries=list()),'registry_hash'))
  r<-.cr_rs_sealed(registry,'registry_hash','registry'); entries<-.cr_data_rows(r$entries,'registry.entries'); .cr_data_unique(entries,c('model_id','model_version'),'registry entries')
  for(e in entries) { .cr_data_required(e,c('model_id','model_version','registered_at','model_hash','bundle')); .cr_data_date(e$registered_at,'registered_at'); if(!identical(.cr_hash(e$bundle),e$model_hash)) .cr_error('RATING_INTEGRITY','Registered bundle hash mismatch'); bundle<-.cr_rs_object(e$bundle,'registered bundle');model<-.cr_model(bundle$model); if(model$model_id!=e$model_id||model$model_version!=e$model_version) .cr_error('RATING_MODEL_IDENTITY','Registry identity mismatch') };r
}
register_rating_model_version <- function(registry,bundle,registration) {
  registry<-.cr_rs_registry(registry); bundle<-.cr_rs_object(bundle,'bundle'); registration<-.cr_rs_object(registration,'registration'); .cr_data_required(bundle,c('model','dependencies','configuration')); model<-.cr_model(bundle$model);bundle$model<-model; .cr_rs_object(bundle$dependencies,'dependencies'); .cr_rs_object(bundle$configuration,'configuration'); .cr_data_required(registration,c('model_id','model_version','registered_at'))
  if(registration$model_id!=model$model_id||registration$model_version!=model$model_version) .cr_error('RATING_MODEL_IDENTITY','Registration must match model identity')
  when<-.cr_data_date(registration$registered_at,'registered_at');if(.cr_data_date(model$training$known_at,'model.training.known_at')>when) .cr_error('RATING_DATE_ORDER','Registration precedes training knowledge')
  digest<-.cr_hash(bundle);matches<-Filter(function(e)e$model_id==model$model_id&&e$model_version==model$model_version,registry$entries)
  if(length(matches)) {if(!identical(matches[[1]]$model_hash,digest)||!identical(.cr_hash(matches[[1]]$registration),.cr_hash(registration))) .cr_error('RATING_VERSION_CONFLICT','Existing version has different content or metadata'); return(.cr_result(registry,'rating_system.register_rating_model_version',diagnostics=list(idempotent=TRUE)))}
  registry$entries[[length(registry$entries)+1L]]<-list(model_id=model$model_id,model_version=model$model_version,registered_at=registration$registered_at,model_hash=digest,registration=registration,bundle=bundle);registry$entries<-.cr_rs_sort(registry$entries,c('model_id','model_version'))
  .cr_result(.cr_rs_seal(registry,'registry_hash'),'rating_system.register_rating_model_version',diagnostics=list(idempotent=FALSE))
}
select_effective_model <- function(registry,assignments,profile_id,purpose,as_of,known_at) {
  if(inherits(assignments,"CalcResult")||(is.list(assignments)&&identical(assignments$kind,"ModelAssignmentHistory"))) assignments<-.cr_mon_projection(assignments,known_at,role="champion")
  registry<-.cr_rs_registry(registry);d<-.cr_rs_dates(as_of,known_at);.cr_rs_string(profile_id,'profile_id');.cr_rs_string(purpose,'purpose');assignments<-.cr_data_rows(assignments,'assignments');.cr_data_unique(assignments,'assignment_id','assignments');scoped<-list();active<-list()
  for(row in assignments) {.cr_data_required(row,c('assignment_id','profile_id','purpose','model_id','model_version','model_hash'));.cr_rs_interval(row);if(row$profile_id==profile_id&&row$purpose==purpose&&.cr_data_date(row$known_at,'known_at')<=d$k) {scoped[[length(scoped)+1L]]<-row;if(.cr_rs_effective(row,d$a,d$k))active[[length(active)+1L]]<-row}}
  status<-'MISSING_MODEL';selected<-NULL
  if(length(active)>1L)status<-'AMBIGUOUS_MODEL' else if(length(active)==1L) {assignment<-active[[1]];entries<-Filter(function(e)e$model_id==assignment$model_id&&e$model_version==assignment$model_version&&.cr_data_date(e$registered_at,'registered_at')<=d$k,registry$entries);if(length(entries)) {if(!identical(entries[[1]]$model_hash,assignment$model_hash)) .cr_error('RATING_INTEGRITY','Assignment hash differs from registered bundle');status<-'SELECTED';selected<-c(list(assignment=assignment),entries[[1]])}} else if(length(scoped)) status<-if(all(vapply(scoped,function(r).cr_data_date(r$effective_from,'effective_from')>d$a,logical(1))))'NOT_YET_EFFECTIVE' else 'EXPIRED_MODEL'
  .cr_result(list(status=status,selected=selected,candidate_assignment_ids=as.list(sort(vapply(active,function(r)r$assignment_id,character(1)),method='radix')),profile_id=profile_id,purpose=purpose,as_of=as_of,known_at=known_at),'rating_system.select_effective_model')
}
compose_risk_assessment <- function(assessment_id,subject,components,binding,as_of,known_at,calculated_at,effects=NULL) {
  .cr_rs_string(assessment_id,'assessment_id');d<-.cr_rs_dates(as_of,known_at);if(.cr_data_date(calculated_at,'calculated_at')<d$k) .cr_error('RATING_DATE_ORDER','Calculation precedes knowledge cutoff');subject<-.cr_rs_object(subject,'subject');binding<-.cr_rs_object(binding,'binding');.cr_data_required(subject,c('subject_id','subject_type'));if(!(subject$subject_type %in% .cr_rs_types)) .cr_error('RATING_SCHEMA','Unsupported subject type');.cr_data_required(binding,c('profile_id','profile_version','model_id','model_version','model_hash','input_hash'));for(key in names(binding)) .cr_rs_string(binding[[key]],key)
  components<-.cr_data_rows(components,'components');.cr_data_unique(components,'component_id','components');effects<-.cr_data_rows(if(is.null(effects))list() else effects,'effects');.cr_data_unique(effects,'effect_id','effects');conflicts<-list();definitions<-list();currencies<-character();ids<-vapply(components,function(c)c$component_id,character(1))
  for(c in components) {.cr_data_required(c,c('component_id','quantity','value','subject_id','subject_type','variant','definition'));if(!(c$subject_type %in% .cr_rs_types)||!(c$quantity %in% c('PD','GRADE','LGD','EAD','EL','SCORE'))) .cr_error('RATING_SCHEMA','Unsupported quantity or subject type');.cr_rs_string(c$variant,'component.variant');target<-.cr_rs_object(c$definition,'component.definition');.cr_data_required(target,c('event','horizon','time_unit','probability_measure','conditioning'));if(.cr_rs_number(target$horizon,'horizon')<=0||!(target$time_unit %in% c('days','months','years'))||!(target$probability_measure %in% c('PHYSICAL','RISK_NEUTRAL'))) .cr_error('RATING_SCHEMA','Invalid component definition')
    if(c$quantity=='GRADE') {.cr_rs_string(c$value,'grade');.cr_data_required(c,c('scale_id','scale_version','graded_quantity'));if(!(c$graded_quantity %in% c('PD','EL','SCORE'))) .cr_error('RATING_SCHEMA','Grade needs graded quantity')} else {value<-.cr_rs_number(c$value,'component.value');if(c$quantity=='PD'&&(value<0||value>1)) .cr_error('RATING_SCHEMA','PD outside [0,1]');if(c$quantity=='EAD'&&value<0) .cr_error('RATING_SCHEMA','EAD negative')}
    if(c$quantity %in% c('EAD','EL')) {.cr_data_required(c,'currency');currencies<-c(currencies,.cr_rs_string(c$currency,'currency'))}
    if((c$subject_id!=subject$subject_id||c$subject_type!=subject$subject_type)&&is.null(c$relationship_id))conflicts[[length(conflicts)+1L]]<-list(component_id=c$component_id,code='UNLINKED_SUBJECT_LEVEL')
    key<-.cr_hash(list(c$subject_type,c$subject_id,c$variant));if(is.null(definitions[[key]]))definitions[[key]]<-list();definitions[[key]][[length(definitions[[key]])+1L]]<-c
  }
  for(group in definitions) {group_ids<-as.list(sort(vapply(group,function(c)c$component_id,character(1)),method='radix'));if(length(unique(vapply(group,function(c).cr_hash(c$definition),character(1))))>1L)conflicts[[length(conflicts)+1L]]<-list(component_ids=group_ids,code='TARGET_DEFINITION_CONFLICT');if(length(unique(vapply(group,function(c)c$quantity,character(1))))<length(group))conflicts[[length(conflicts)+1L]]<-list(component_ids=group_ids,code='DUPLICATE_QUANTITY_VARIANT')}
  if(length(unique(currencies))>1L)conflicts[[length(conflicts)+1L]]<-list(code='MIXED_CURRENCY',currencies=as.list(sort(unique(currencies),method='radix')))
  orders<-numeric();edges<-list();producers<-list();component_map<-setNames(components,ids)
  for(effect in effects) {.cr_data_required(effect,c('effect_id','kind','order','level','input_component_id','output_component_id','reason'));if(!(effect$kind %in% c('support','transfer','override','cashflow'))||!(effect$level %in% .cr_rs_types)) .cr_error('RATING_SCHEMA','Unsupported effect');.cr_data_days(effect$order,'effect.order');.cr_rs_string(effect$reason,'effect.reason');if(effect$order %in% orders||!(effect$input_component_id %in% ids)||!(effect$output_component_id %in% ids)||effect$input_component_id==effect$output_component_id) .cr_error('RATING_EFFECT_CONFLICT','Effect requires unique order and existing distinct components');orders<-c(orders,effect$order);if(!is.null(edges[[effect$output_component_id]])) .cr_error('RATING_EFFECT_CONFLICT','Several effects overwrite output component');if(component_map[[effect$output_component_id]]$subject_type!=effect$level) .cr_error('RATING_EFFECT_CONFLICT','Effect level must match output');edges[[effect$output_component_id]]<-effect$input_component_id;producers[[effect$output_component_id]]<-effect$order}
  for(effect in effects) if(!is.null(producers[[effect$input_component_id]])&&producers[[effect$input_component_id]]>=effect$order) .cr_error('RATING_EFFECT_CONFLICT','Effect order must follow its input producer')
  for(node in names(edges)) {seen<-character();cursor<-node;while(cursor %in% names(edges)) {if(cursor %in% seen) .cr_error('RATING_EFFECT_CONFLICT','Effect cycle');seen<-c(seen,cursor);cursor<-edges[[cursor]]}}
  value<-list(schema_version='1.0',assessment_id=assessment_id,subject=subject,binding=binding,as_of=as_of,known_at=known_at,calculated_at=calculated_at,components=.cr_rs_sort(components,'component_id'),effects=.cr_rs_sort(effects,'order'),conflicts=conflicts,composition_status=if(length(conflicts))'CONFLICT' else 'CONSISTENT',state='DRAFT',history=list())
  .cr_result(.cr_rs_seal(value,'assessment_hash'),'rating_system.compose_risk_assessment',limitations='Composition preserves supplied quantities; it does not infer adjustments, copy PD across levels or approve credit.')
}
check_assessment_freshness <- function(assessment,policy,events,as_of,known_at) {
  assessment<-.cr_rs_sealed(assessment,'assessment_hash','assessment');policy<-.cr_rs_object(policy,'freshness policy');d<-.cr_rs_dates(as_of,known_at);.cr_data_required(policy,c('maximum_age_days','maximum_information_age_days','trigger_types'));for(key in c('maximum_age_days','maximum_information_age_days')).cr_data_days(policy[[key]],key);if(!is.list(policy$trigger_types)||any(!vapply(policy$trigger_types,function(t)is.character(t)&&length(t)==1L,logical(1)))) .cr_error('RATING_SCHEMA','trigger_types must be a list')
  if(.cr_data_date(assessment$as_of,'assessment.as_of')>d$a||.cr_data_date(assessment$known_at,'assessment.known_at')>d$k) .cr_error('RATING_DATE_ORDER','Assessment unavailable at historical date');if(any(vapply(assessment$history,function(h).cr_data_date(h$event$known_at,'history.known_at')>d$k,logical(1)))) .cr_error('RATING_DATE_ORDER','Lifecycle state after cutoff');findings<-list();add<-function(x)findings[[length(findings)+1L]]<<-x
  if(as.numeric(d$a-.cr_data_date(assessment$as_of,'assessment.as_of'))>policy$maximum_age_days)add(list(code='ASSESSMENT_AGE'));if(as.numeric(d$k-.cr_data_date(assessment$known_at,'assessment.known_at'))>policy$maximum_information_age_days)add(list(code='INFORMATION_AGE'));if(!is.null(policy$effective_to)&&d$a>=.cr_data_date(policy$effective_to,'effective_to'))add(list(code='PROFILE_EXPIRED'));superseded<-assessment$state=='SUPERSEDED';events<-.cr_data_rows(events,'events');.cr_data_unique(events,'event_id','events')
  for(event in .cr_rs_sort(events,'event_id')) {.cr_data_required(event,c('event_id','subject_id','type','occurred_at','known_at'));occurrence<-.cr_data_date(event$occurred_at,'occurred_at');available<-.cr_data_date(event$known_at,'known_at');if(available<occurrence) .cr_error('RATING_DATE_ORDER','Event known before occurrence');if(event$subject_id==assessment$subject$subject_id&&occurrence<=d$a&&available<=d$k&&available>.cr_data_date(assessment$known_at,'assessment.known_at')) {if(identical(event$supersedes_assessment_id,assessment$assessment_id)){superseded<-TRUE;add(list(code='SUPERSEDED',event_id=event$event_id))}else if(event$type %in% unlist(policy$trigger_types))add(list(code='MATERIAL_EVENT',event_id=event$event_id))}}
  .cr_result(list(status=if(superseded)'SUPERSEDED' else if(length(findings))'STALE' else 'CURRENT',assessment_id=assessment$assessment_id,findings=findings,as_of=as_of,known_at=known_at),'rating_system.check_assessment_freshness')
}
transition_assessment_state <- function(assessment,event,transitions) {
  a<-.cr_rs_sealed(assessment,'assessment_hash','assessment');event<-.cr_rs_object(event,'event');.cr_data_required(event,c('event_id','type','occurred_at','known_at','reason','gates'));.cr_rs_string(event$reason,'reason');gates<-.cr_rs_object(event$gates,'gates');d<-.cr_rs_dates(event$occurred_at,event$known_at)
  if(d$a<.cr_data_date(a$calculated_at,'calculated_at')||d$k<.cr_data_date(a$known_at,'assessment.known_at')) .cr_error('RATING_DATE_ORDER','Lifecycle event precedes assessment');if(any(vapply(a$history,function(h)h$event$event_id==event$event_id,logical(1)))) .cr_error('RATING_EVENT_CONFLICT','Lifecycle event already applied');if(length(a$history)) {last<-a$history[[length(a$history)]]$event;if(d$a<.cr_data_date(last$occurred_at,'occurred_at')||d$k<.cr_data_date(last$known_at,'known_at')) .cr_error('RATING_DATE_ORDER','Lifecycle history must remain ordered')}
  transitions<-.cr_data_rows(transitions,'transitions');states<-c('DRAFT','SUBMITTED','REVIEWED','FINAL','SUPERSEDED');for(t in transitions) {.cr_data_required(t,c('from_state','to_state','event_type','required_gates'));if(!(t$from_state %in% states)||!(t$to_state %in% states)||!is.list(t$required_gates)) .cr_error('RATING_SCHEMA','Malformed transition table')};matches<-Filter(function(t)t$from_state==a$state&&t$event_type==event$type,transitions);if(length(matches)!=1L) .cr_error('RATING_TRANSITION','Transition absent or ambiguous');t<-matches[[1]];if(any(!vapply(t$required_gates,function(g)identical(gates[[g]],TRUE),logical(1)))) .cr_error('RATING_GATE','Required gates not explicitly true');if(t$to_state=='FINAL'&&a$composition_status!='CONSISTENT') .cr_error('RATING_GATE','Conflicted composition cannot be finalized');if(a$state=='SUPERSEDED'||(a$state=='FINAL'&&t$to_state!='SUPERSEDED')) .cr_error('RATING_TRANSITION','Final history only allows explicit superseding transition')
  a$history[[length(a$history)+1L]]<-list(from_state=a$state,to_state=t$to_state,previous_assessment_hash=a$assessment_hash,event=event);a$state<-t$to_state
  .cr_result(.cr_rs_seal(a,'assessment_hash'),'rating_system.transition_assessment_state',limitations='FINAL is a local processing status, not institutional or regulatory approval.')
}
.cr_rs_execute <- function(request,registry,cutoff) {
  .cr_data_required(request,c('row_id','known_at','model_id','model_version','model_hash','recipe','input'));if(.cr_data_date(request$known_at,'request.known_at')>cutoff) .cr_error('RATING_REQUEST_UNAVAILABLE','Request unavailable at cutoff');entries<-Filter(function(e)e$model_id==request$model_id&&e$model_version==request$model_version,registry$entries);if(!length(entries)||.cr_data_date(entries[[1]]$registered_at,'registered_at')>.cr_data_date(request$known_at,'request.known_at')) .cr_error('RATING_MISSING_MODEL','Pinned historical model unavailable');entry<-entries[[1]];if(!identical(entry$model_hash,request$model_hash)) .cr_error('RATING_INTEGRITY','Pinned model hash mismatch');recipe<-.cr_rs_object(request$recipe,'recipe');inputs<-.cr_rs_object(request$input,'input');.cr_data_required(recipe,c('method','version','parameters'));parameters<-.cr_rs_object(recipe$parameters,'recipe.parameters');if(identical(recipe$method,'assessment_pipeline')&&identical(recipe$version,'2.0'))return(.cr_rs_execute_pipeline(request,entry));.cr_rx_dated(parameters,.cr_data_date(request$known_at,'request.known_at'),'recipe parameters');if(!identical(recipe$version,'1.0')) .cr_error('RATING_RECIPE','Unsupported recipe version')
  if(recipe$method=='application_risk') {if(!setequal(names(inputs),'snapshot')||any(!names(parameters) %in% c('target','offset','calibrator'))||!('target' %in% names(parameters))) .cr_error('RATING_RECIPE','Application recipe requires snapshot and target');snapshot<-.cr_rs_object(inputs$snapshot,'application snapshot');.cr_data_required(snapshot,'information_cutoff');if(.cr_data_date(snapshot$information_cutoff,'snapshot.information_cutoff')>.cr_data_date(request$known_at,'request.known_at')) .cr_error('RATING_REQUEST_UNAVAILABLE','Snapshot exceeds request knowledge');result<-do.call(predict_application_risk,c(list(snapshot=inputs$snapshot,model=entry$bundle$model),parameters));value<-result$value
  } else if(recipe$method=='behavioral_risk') {if(!setequal(names(inputs),'snapshot')||any(!names(parameters) %in% c('target','offset','calibrator'))||!('target' %in% names(parameters))) .cr_error('RATING_RECIPE','Behavioral recipe requires snapshot and target');snapshot<-.cr_rs_object(inputs$snapshot,'behavioral snapshot');.cr_data_required(snapshot,'known_at');if(.cr_data_date(snapshot$known_at,'snapshot.known_at')>.cr_data_date(request$known_at,'request.known_at')) .cr_error('RATING_REQUEST_UNAVAILABLE','Snapshot exceeds request knowledge');result<-do.call(predict_behavioral_risk,c(list(snapshot=inputs$snapshot,model=entry$bundle$model),parameters));value<-result$value
  } else if(recipe$method %in% c('binary_glm','pd_model')) {if(recipe$method=='binary_glm'&&!identical(entry$bundle$model$method_id,'classification.fit_binary_glm')) .cr_error('RATING_RECIPE','Binary GLM recipe requires a binary GLM artifact');if(!setequal(names(inputs),c('X','feature_order'))||any(!names(parameters) %in% c('expected_target','offset'))||!('expected_target' %in% names(parameters))) .cr_error('RATING_RECIPE','GLM recipe requires X/features and expected_target');X<-inputs$X;if(!is.null(parameters$offset))parameters$offset<-unlist(parameters$offset);result<-do.call(predict_pd,c(list(fitted_model=entry$bundle$model,X=X,feature_order=unlist(inputs$feature_order)),parameters));value<-as.list(as.numeric(result$value))
  } else .cr_error('RATING_RECIPE','Unsupported declarative recipe')
  list(row_id=request$row_id,status='OK',value=value,error_code=NULL,input_hash=.cr_hash(inputs),recipe_hash=.cr_hash(recipe),model_hash=entry$model_hash,result_hash=.cr_hash(value))
}
rate_subject_batch <- function(requests,registry,batch_id,known_at) {
  .cr_rs_string(batch_id,'batch_id');cutoff<-.cr_data_date(known_at,'known_at');registry<-.cr_rs_registry(registry);requests<-.cr_data_rows(requests,'requests');.cr_data_unique(requests,'row_id','requests');requests<-.cr_rs_sort(requests,'row_id');output<-list()
  for(request in requests) {output[[length(output)+1L]]<-tryCatch(.cr_rs_execute(request,registry,cutoff),creditratingsystem_error=function(e)list(row_id=request$row_id,status='ERROR',value=NULL,error_code=e$code,input_hash=.cr_hash(request$input),recipe_hash=.cr_hash(request$recipe),model_hash=request$model_hash,result_hash=NULL))}
  value<-list(schema_version='1.0',batch_id=batch_id,known_at=known_at,rows=output,request_hash=.cr_hash(requests),registry_hash=registry$registry_hash)
  .cr_result(.cr_rs_seal(value,'batch_hash'),'rating_system.rate_subject_batch',diagnostics=list(success_count=sum(vapply(output,function(r)r$status=='OK',logical(1))),error_count=sum(vapply(output,function(r)r$status=='ERROR',logical(1)))),limitations='Pinned data-only pipelines support native calculation, pricing and explicit simulation, frozen empirical artifacts and local lifecycle replay; no callbacks or executable deserialization.')
}
apply_assessment_event <- function(state,event,dependencies,known_at) {
  state<-if(is.null(state)).cr_rs_seal(list(schema_version='1.0',processed=list(),applications=list()),'state_hash') else .cr_rs_sealed(state,'state_hash','event state');event<-.cr_rs_object(event,'event');.cr_data_required(event,c('event_id','revision','occurred_at','known_at','dependencies','payload'));.cr_rs_string(event$revision,'revision');.cr_rs_dates(event$occurred_at,event$known_at);cutoff<-.cr_data_date(known_at,'known_at');digest<-.cr_hash(event);if(any(vapply(state$processed,function(r).cr_data_date(r$event$known_at,'processed.known_at')>cutoff,logical(1)))) .cr_error('RATING_DATE_ORDER','Event state contains history after cutoff');previous<-Filter(function(r)r$event_id==event$event_id&&r$revision==event$revision,state$processed)
  if(length(previous)) {if(!identical(previous[[1]]$event_hash,digest)) .cr_error('RATING_EVENT_CONFLICT','Same event ID/revision differs');application<-Filter(function(r)r$event_id==event$event_id&&r$revision==event$revision,state$applications)[[1]];return(.cr_result(list(status='DUPLICATE',state=state,affected_assessment_ids=application$affected_assessment_ids),'rating_system.apply_assessment_event'))}
  if(.cr_data_date(event$known_at,'event.known_at')>cutoff)return(.cr_result(list(status='DEFERRED',state=state,affected_assessment_ids=list()),'rating_system.apply_assessment_event'))
  revisions<-Filter(function(r)r$event_id==event$event_id,state$processed);if(length(revisions)) {last<-revisions[[length(revisions)]];if(!identical(event$corrects_revision,last$revision)) .cr_error('RATING_EVENT_CONFLICT','Correction must refer to latest previous revision');if(.cr_data_date(event$known_at,'known_at')<.cr_data_date(last$event$known_at,'known_at')) .cr_error('RATING_DATE_ORDER','Correction known before earlier revision')}else if(!is.null(event$corrects_revision)) .cr_error('RATING_EVENT_CONFLICT','Correction refers to missing earlier event')
  event_deps<-.cr_data_rows(event$dependencies,'event.dependencies');for(dep in event_deps){.cr_data_required(dep,c('type','id'));.cr_rs_string(dep$type,'dependency.type');.cr_rs_string(dep$id,'dependency.id')};dependencies<-.cr_data_rows(dependencies,'dependencies');for(dep in dependencies).cr_data_required(dep,c('assessment_id','dependency_type','dependency_id'));matched<-Filter(function(d)any(vapply(event_deps,function(e)e$type==d$dependency_type&&e$id==d$dependency_id,logical(1))),dependencies);affected<-as.list(sort(unique(vapply(matched,function(d)d$assessment_id,character(1))),method='radix'))
  state$processed[[length(state$processed)+1L]]<-list(event_id=event$event_id,revision=event$revision,event_hash=digest,event=event);state$applications[[length(state$applications)+1L]]<-list(event_id=event$event_id,revision=event$revision,affected_assessment_ids=affected,dependency_hash=.cr_hash(dependencies))
  .cr_result(list(status='APPLIED',state=.cr_rs_seal(state,'state_hash'),affected_assessment_ids=affected),'rating_system.apply_assessment_event',limitations='Projection identifies affected assessments; it does not mutate risk values, accounts or external systems.')
}
replay_assessment_history <- function(requests,registry,expected,known_at,replay_id='replay') {
  expected<-.cr_data_rows(expected,'expected');.cr_data_unique(expected,'row_id','expected');for(row in expected).cr_data_required(row,c('row_id','input_hash','recipe_hash','model_hash','result_hash'));expectations<-setNames(expected,vapply(expected,function(r)r$row_id,character(1)));batch<-tryCatch(rate_subject_batch(requests,registry,replay_id,known_at)$value,creditratingsystem_error=identity);if(inherits(batch,'creditratingsystem_error'))return(.cr_result(list(status='NOT_REPRODUCIBLE',batch=NULL,verified_row_ids=list(),findings=list(list(row_id=NULL,code=batch$code))),'rating_system.replay_assessment_history',limitations='Invalid supplied artifact/history content prevents historical reproduction.'));findings<-list();verified<-list()
  for(row in batch$rows) {reference<-expectations[[row$row_id]];if(row$status!='OK')findings[[length(findings)+1L]]<-list(row_id=row$row_id,code=row$error_code) else if(is.null(reference))findings[[length(findings)+1L]]<-list(row_id=row$row_id,code='MISSING_REFERENCE')else {fields<-c('input_hash','recipe_hash','model_hash','result_hash');if(is.list(row$value)&&identical(row$value$schema_version,'2.0'))fields<-c(fields,'assessment_hash','event_state_hash','artifact_manifest_hash','innovation_hash','decision_hash');mismatches<-fields[vapply(fields,function(f)!f %in% names(reference)||!identical(row[[f]],reference[[f]]),logical(1))];if(length(mismatches))findings[[length(findings)+1L]]<-list(row_id=row$row_id,code='REPLAY_MISMATCH',fields=as.list(mismatches))else verified[[length(verified)+1L]]<-row$row_id}}
  found<-vapply(batch$rows,function(r)r$row_id,character(1));for(id in sort(setdiff(names(expectations),found),method='radix'))findings[[length(findings)+1L]]<-list(row_id=id,code='MISSING_REQUEST')
  .cr_result(list(status=if(!length(findings))'REPRODUCED' else 'NOT_REPRODUCIBLE',batch=batch,verified_row_ids=verified,findings=findings),'rating_system.replay_assessment_history',limitations='Replay uses only supplied pinned artifacts and historical cutoff; source names without matching hashes are insufficient.')
}
